alter table public.product_subscriptions drop constraint if exists product_subscriptions_amount_cents_check;
alter table public.product_subscriptions add constraint product_subscriptions_amount_cents_check check(amount_cents in (19900,29900,39900,44900,54900));
alter table public.visits add column if not exists ticket_value_cents integer;
alter table public.reward_redemptions add column if not exists reward_image_url text;
alter table public.reward_redemptions add column if not exists reward_value_cents integer;
alter table public.reward_redemptions add column if not exists redemption_image_url text;
alter table public.loyalty_programs add column if not exists reward_image_url text;
create table if not exists public.business_branches(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,address text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.google_reviews(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,reviewer_name text,rating numeric(2,1),review_text text,review_date date,response_text text,responded_at timestamptz,period_start date not null default date_trunc('month',now())::date,created_at timestamptz not null default now());
create table if not exists public.google_review_period_summaries(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,period_start date not null,summary text not null,created_at timestamptz not null default now(),unique(business_id,period_start));
create table if not exists public.business_zone_comparisons(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,period_start date not null,business_rating numeric(2,1),business_review_count integer,area_rating numeric(2,1),area_review_count integer,created_at timestamptz not null default now(),unique(business_id,period_start));
create table if not exists public.business_period_reports(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,plan_code text not null,period_start date not null,period_end date not null,snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(business_id,period_start));
create table if not exists public.business_admin_tasks(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,task_type text not null,due_at date not null default current_date,period_start date not null default date_trunc('month',now())::date,completed_at timestamptz,note text,created_at timestamptz not null default now());
alter table public.business_branches enable row level security; alter table public.google_reviews enable row level security; alter table public.google_review_period_summaries enable row level security; alter table public.business_zone_comparisons enable row level security; alter table public.business_period_reports enable row level security; alter table public.business_admin_tasks enable row level security;
create policy "members read branches" on public.business_branches for select to authenticated using(public.is_business_member(business_id));
create policy "managers manage branches" on public.business_branches for all to authenticated using(exists(select 1 from public.business_members m where m.business_id=business_branches.business_id and m.user_id=auth.uid() and m.role in ('owner','manager'))) with check(exists(select 1 from public.business_members m where m.business_id=business_branches.business_id and m.user_id=auth.uid() and m.role in ('owner','manager')));
create policy "members read reviews" on public.google_reviews for select to authenticated using(public.is_business_member(business_id));
create policy "members read summaries" on public.google_review_period_summaries for select to authenticated using(public.is_business_member(business_id));
create policy "members read comparisons" on public.business_zone_comparisons for select to authenticated using(public.is_business_member(business_id));
create policy "members read reports" on public.business_period_reports for select to authenticated using(public.is_business_member(business_id));
grant select on public.business_branches,public.google_reviews,public.google_review_period_summaries,public.business_zone_comparisons,public.business_period_reports to authenticated;
grant all on public.business_branches,public.google_reviews,public.google_review_period_summaries,public.business_zone_comparisons,public.business_period_reports,public.business_admin_tasks to service_role;
